export type UploadApiErrorCode =
  | "unauthenticated"
  | "unauthorized"
  | "validation_error"
  | "network_error"
  | "unexpected_response";

export class UploadApiError extends Error {
  public readonly code: UploadApiErrorCode;
  public readonly status?: number;

  constructor(message: string, options: { code: UploadApiErrorCode; status?: number }) {
    super(message);
    this.name = "UploadApiError";
    this.code = options.code;
    this.status = options.status;
  }
}

export function resolveApiBaseUrl(env: Record<string, string | undefined> = process.env): string {
  const baseUrl = env.NEXT_PUBLIC_API_BASE_URL?.trim() || "/api";
  return baseUrl.endsWith("/") ? baseUrl.slice(0, -1) : baseUrl;
}

